
import { ConsumableType, ILootDto, LootItemType } from "../types";

export function mapConsumableRecordToLootDto(rewards: Record<ConsumableType, number>): ILootDto[] {
  const map: Record<ConsumableType, LootItemType> = {
    [ConsumableType.UNDO]: LootItemType.UNDO,
    [ConsumableType.HINT]: LootItemType.HINT,
    [ConsumableType.MAGIC]: LootItemType.MAGIC,
    [ConsumableType.VISION]: LootItemType.VISION,
  };
  return Object.entries(rewards)
    .map(([key, amount]) => ({ type: map[key as ConsumableType], amount }))
    .filter((dto) => dto.amount > 0);
}
