import { Align, AlignMethod, layoutChain } from "@kvisaz/phaser-sugar";
import { OverlayScene } from "../../../common/scenes";
import { getLocalizedText, ViewElementBuilder } from "../../../assets";
import { GameServiceProvider } from "../../../services";
import { LootBoxes, LootParticles, LootSideBar } from "../../shared/components";
import { sceneTimeout, TypedEventsEmitter } from "../../../common";
import { IGameLogicCommandEvents, IGameViewEvents } from "../logic";
import { ConsumableType, mapConsumableRecordToLootDto, SoundKey } from "../../../logic";
import { FullscreenOverlay } from "../../../common/game-core";

interface IProps {
  scene: Phaser.Scene;
  commands: TypedEventsEmitter<IGameLogicCommandEvents>;
  viewEvents: TypedEventsEmitter<IGameViewEvents>;
}

export class RewardAdsOverlay {
  private readonly builder: ViewElementBuilder;
  private readonly overlayScene: Phaser.Scene;
  private overlay?: FullscreenOverlay;
  private lootSideBar?: LootSideBar;
  private lootParticles?: LootParticles;
  private lootBoxes?: LootBoxes;
  private busy = false;
  private unSubs: Array<() => void> = [];
  private readonly gameService = GameServiceProvider.get();

  constructor(private props: IProps) {
    OverlayScene.attach(props.scene);
    this.overlayScene = OverlayScene.get(props.scene);
    this.builder = new ViewElementBuilder(this.overlayScene);
    this.subscribe();
  }

  destroy() {
    this.unSubs.forEach((u) => u());
    this.unSubs.length = 0;
    this.clearScene();
  }

  private subscribe() {
    this.unSubs.push(
      this.props.commands.on("showRewardAd", (data) => this.showRewardAd(data.rewardsAmount)),
    );
  }

  private async showRewardAd(rewardsAmount: Record<ConsumableType, number>) {
    if (this.busy) return;
    this.busy = true;
    this.pauseParentScene();
    this.createOverlay();
    this.gameService.showRewardedAd((args) => this.onAdClose(args, rewardsAmount));
  }

  private onAdClose(
    args: { wasShown: boolean; error?: string; isReward: boolean },
    rewardsAmount: Record<ConsumableType, number>,
  ) {
    if (!args.isReward || !args.wasShown) {
      this.finishWithReward({ ...args, rewardsAmount: undefined });
      return;
    }

    const loots = mapConsumableRecordToLootDto(rewardsAmount);
    const clickedBounds =
      this.lootBoxes?.getBounds() ??
      new Phaser.Geom.Rectangle(
        this.overlayScene.scale.width / 2,
        this.overlayScene.scale.height / 2,
        0,
        0,
      );

    this.overlayScene.sound.play(SoundKey.chestSlam);
    this.lootBoxes?.openRandomChest();
    const delay = this.gameService.getGameConfig().ads.rewardAdAnimation.lifeTimeBetweenLastParticleAndClose;
    this.lootParticles?.emit({
      loots,
      clickedBounds,
      onComplete: () => {
        sceneTimeout({
          scene: this.overlayScene,
          delay,
          callback: () => {
            this.finishWithReward({ ...args, rewardsAmount });
          },
        });
      },
    });
  }

  private finishWithReward(result: {
    wasShown: boolean;
    error?: string;
    isReward: boolean;
    rewardsAmount?: Record<ConsumableType, number>;
  }) {
    this.clearScene();
    this.props.viewEvents.emit("onRewardAdClose", result);
    this.props.viewEvents.emit("onRewardShowAdClose", {});
    this.resumeParentScene();
    this.busy = false;
  }

  private createOverlay() {
    this.clearScene();
    const scene = this.overlayScene;

    this.overlay = new FullscreenOverlay({ scene, interactive: true });

    this.createSidebar(scene);
    this.createLootParticles(scene);

    const title = this.builder.textMain(getLocalizedText("ads.reward.title"), {
      fontSize: "48px",
      weight: "bold",
      color: "#ffffff",
    });

    const { rewardAdAnimation } = this.gameService.getGameConfig().ads;
    this.lootBoxes = new LootBoxes({
      scene,
      amount: 1,
      animationConfig: {
        shakingDuration: rewardAdAnimation.lootBoxShakingDuration,
      },
      onLootBoxClick: () => {
        // раскрытие и полет произойдут после закрытия рекламы
      },
    });

    const content = scene.add.container(0, 0, [title, this.lootBoxes]);
    layoutChain({
      children: [title, this.lootBoxes],
      alignToNext: AlignMethod.BOTTOM_TO,
      nextOffsetY: 32,
      alignToAnchor: AlignMethod.CENTER,
    });

    const align = new Align();
    align.anchorSceneScreen(scene).center(content);
  }

  private createSidebar(scene: Phaser.Scene) {
    this.lootSideBar = new LootSideBar({ scene });
    const align = new Align();
    align.anchorSceneScreen(scene).leftIn(this.lootSideBar, 33).bottomIn(this.lootSideBar, -86);
    this.lootSideBar.setVisible(true);
  }

  private createLootParticles(scene: Phaser.Scene) {
    const rewardAdAnimation = this.gameService.getGameConfig().ads.rewardAdAnimation;
    this.lootParticles = new LootParticles({
      scene,
      animationConfig: {
        explodeDuration: rewardAdAnimation.lootBoxExplodeDuration,
        flyDurationMin: rewardAdAnimation.lootFlyDuration,
        flyDurationMax: rewardAdAnimation.lootFlyDuration,
        flyDelay: rewardAdAnimation.lootFlyDelay,
      },
      onLootItemCollectStart: () => {},
      onLootItemCollected: (lootDto) => {
        scene.sound.play(SoundKey.coinFlip);
        this.lootSideBar?.collect(lootDto);
      },
    });
  }

  private clearScene() {
    const childScene = this.overlayScene;
    this.overlay?.destroy();
    childScene.children.removeAll(true);
    this.overlay = undefined;
    this.lootSideBar = undefined;
    this.lootParticles = undefined;
    this.lootBoxes = undefined;
  }

  private pauseParentScene() {
    this.props.scene.sound.pauseAll();
    this.props.scene.scene.pause();
  }

  private resumeParentScene() {
    this.props.scene.sound.resumeAll();
    this.props.scene.scene.resume();
  }
}
