import {
  getCardClassic52Deck,
  IClassicCardDto,
  Observable,
  shuffleArray,
  State,
  TypedEventsEmitter,
} from "../../../common";
import {
  GameLogicState,
  IGameLogicCommandEvents,
  IGameViewEvents,
  KlondikeLiveSnapshot,
} from "./types";
import { getDefaultState } from "./config";
import { GameService, GameServiceProvider } from "../../../services";
import { ConsumableType, GoodyType, IGameConfig } from "../../../logic";
import { makeLoots } from "./makeLoots";

interface IProps {
  gameConfig: IGameConfig;
}

export class GameSceneViewLogic {
  private readonly state: State<GameLogicState>;
  private unSubs: (() => void)[];

  private lastKlondikeState: KlondikeLiveSnapshot | undefined;
  private deckCards: IClassicCardDto[];

  public readonly gameSceneLogicCommands: TypedEventsEmitter<IGameLogicCommandEvents>;
  public readonly gameSceneViewEvents: TypedEventsEmitter<IGameViewEvents>;
  private readonly gameService: GameService;

  public observable(): Observable<GameLogicState> {
    return this.state;
  }

  constructor(protected props: IProps) {
    this.unSubs = [];

    /** команды управления и связи с view **/
    this.gameSceneLogicCommands = new TypedEventsEmitter<IGameLogicCommandEvents>();
    this.gameSceneViewEvents = new TypedEventsEmitter<IGameViewEvents>();
    this.unSubs.push(() => {
      this.gameSceneLogicCommands.unSubscribeAll();
      this.gameSceneViewEvents.unSubscribeAll();
    });

    this.gameService = GameServiceProvider.get();
    const consumables = this.gameService.getPlayerData().consumables;

    /**
     * состояние - к сожалению его все равно надо хранить
     * поэтому можно сразу хранить с возможностью подписки
     *  **/
    this.state = new State<GameLogicState>({
      ...getDefaultState(),
      consumableBalance: consumables,
    });
    this.unSubs.push(() => this.state.unSubScribeAll());
    this.subscribeToSaveConsumables();

    this.deckCards = [...getCardClassic52Deck().cards.all];

    this.subscribeToKlondikeGameEvents();
    this.subscribeToUiEvents();
    this.subscribeToAdEvents();
  }

  /** сохраняем consumables при их изменении **/
  private subscribeToSaveConsumables() {
    this.state.on((state) => {
      this.gameService.setPlayerData({
        consumables: state.consumableBalance,
      });
    }, "consumableBalance");
  }

  /** Подписка на события клондайка игры **/
  private subscribeToKlondikeGameEvents() {
    const { gameSceneViewEvents } = this;
    gameSceneViewEvents.on("klondikeStateUpdate", (data) => this.applyKlondikeState(data));
    gameSceneViewEvents.on("klondikeDealFinish", (data) => {
      // what to do?
    });
    gameSceneViewEvents.on("klondikeUndoFinish", (data) => {
      this.consume(ConsumableType.UNDO);
    });
    gameSceneViewEvents.on("klondikeHintFinish", (data) => {
      this.consume(ConsumableType.HINT);
      this.hideOverlay();
    });
    gameSceneViewEvents.on("klondikeVisionFinish", (data) => {
      this.consume(ConsumableType.VISION);
      this.hideOverlay();
    });
    gameSceneViewEvents.on("klondikeMagicFinish", (data) => {
      this.consume(ConsumableType.MAGIC);
      this.hideOverlay();
    });
    gameSceneViewEvents.on("klondikeCompleted", (data) => {
      const loots = makeLoots({
        ...this.props.gameConfig.lootConfig,
      });
      this.gameSceneLogicCommands.emit("showGameFinish", {
        loots,
        score: this.state.getState().score,
      });
    });

    /** при перевороте колоды - запускаем рекламу **/
    gameSceneViewEvents.on("klondikeDeckRecycle", () => {
      if (!this.gameService.isFullAdEnabled) return;
      this.gameSceneLogicCommands.emit("showCommonAd", {});
    });

    gameSceneViewEvents.on("onGameFinishClose", () => {
      const { consumables } = this.gameService.getPlayerData();
      this.state.setState((prev) => ({
        ...prev,
        consumableBalance: consumables,
      }));
      this.startNewGame({ shuffleDeck: true });
    });
  }

  public destroy() {
    this.unSubs.forEach((u) => u());
    this.unSubs.length = 0;
  }

  /** Подписка на события UI **/
  private subscribeToUiEvents() {
    const { gameSceneViewEvents } = this;
    gameSceneViewEvents.on("uiNewGameClick", (data) => {
      this.startNewGame({ shuffleDeck: true });
    });
    gameSceneViewEvents.on("uiReplayClick", (data) => {
      this.startNewGame({ shuffleDeck: false });
    });
    gameSceneViewEvents.on("uiUndoClick", (data) => {
      if (this.isTrickPossible(ConsumableType.UNDO)) {
        this.gameSceneLogicCommands.emit("undoKlondike");
      } else {
        this.tryShowRewardAd(ConsumableType.UNDO);
      }
    });
    gameSceneViewEvents.on("uiHintClick", (data) => {
      if (this.isTrickPossible(ConsumableType.HINT)) {
        this.state.setState((prev) => ({
          ...prev,
          showGoodyOverlay: {
            goody: GoodyType.HINT,
            durationMs: this.props.gameConfig.klondikeConfig.hintDurationMs,
          },
        }));
        this.gameSceneLogicCommands.emit("hintKlondike", {
          durationMs: this.props.gameConfig.klondikeConfig.hintDurationMs,
        });
      } else {
        this.tryShowRewardAd(ConsumableType.HINT);
      }
    });
    gameSceneViewEvents.on("uiVisionClick", (data) => {
      if (this.isTrickPossible(ConsumableType.VISION)) {
        this.state.setState((prev) => ({
          ...prev,
          showGoodyOverlay: {
            goody: GoodyType.VISION,
            durationMs: this.props.gameConfig.klondikeConfig.visionTrickDurationMs,
          },
        }));
        this.gameSceneLogicCommands.emit("visionKlondike", {
          durationMs: this.props.gameConfig.klondikeConfig.visionTrickDurationMs,
        });
      } else {
        this.tryShowRewardAd(ConsumableType.VISION);
      }
    });

    gameSceneViewEvents.on("uiMagicClick", (data) => {
      if (this.isTrickPossible(ConsumableType.MAGIC)) {
        this.state.setState((prev) => ({
          ...prev,
          showGoodyOverlay: { goody: GoodyType.MAGIC },
        }));
        this.gameSceneLogicCommands.emit("magicKlondike", {
          durationMs: this.props.gameConfig.klondikeConfig.magicTrickDurationMs,
        });
      } else {
        this.tryShowRewardAd(ConsumableType.MAGIC);
      }
    });
  }

  startNewGame({ shuffleDeck }: { shuffleDeck: boolean }) {
    const gameService = GameServiceProvider.get();
    const consumableBalance = { ...gameService.getPlayerData().consumables };
    const cards = shuffleDeck ? shuffleArray([...this.deckCards]) : [...this.deckCards];
    this.deckCards = cards;
    this.state.setState((prev) => ({
      ...getDefaultState(),
      /** только consumableBalance восстаналивается из записи **/
      consumableBalance,
    }));

    this.gameSceneLogicCommands.emit("startKlondike", { cards });
  }

  private applyKlondikeState(payload: KlondikeLiveSnapshot) {
    this.lastKlondikeState = payload;

    const prevBalance = this.state.getState().consumableBalance;
    const rewardEnabled = this.gameService.isRewardAdEnabled;
    const canUseOrReward = (type: ConsumableType, possible: boolean) =>
      possible && (prevBalance[type] > 0 || (rewardEnabled && this.rewardAmountFor(type) > 0));
    const consumableButtonsEnabled = {
      UNDO: canUseOrReward(ConsumableType.UNDO, payload.isUndoPossible),
      HINT: canUseOrReward(ConsumableType.HINT, payload.isHintPossible),
      MAGIC: canUseOrReward(ConsumableType.MAGIC, payload.isMagicPossible),
      VISION: canUseOrReward(ConsumableType.VISION, payload.isVisionPossible),
    };

    this.state.setState((prev) => ({
      ...prev,
      consumableButtonsEnabled,
      score: payload.score,
    }));
  }

  private consume(type: ConsumableType) {
    this.state.setState((prev) => {
      const itemBalance = prev.consumableBalance[type];
      const nextBalance = Math.max(0, itemBalance - 1);
      return {
        ...prev,
        consumableBalance: { ...prev.consumableBalance, [type]: nextBalance },
        consumableButtonsEnabled: {
          ...prev.consumableButtonsEnabled,
          [type]: nextBalance > 0 && prev.consumableButtonsEnabled[type],
        },
      };
    });
    if (this.lastKlondikeState) this.applyKlondikeState(this.lastKlondikeState);
  }

  private isTrickPossible(type: ConsumableType): boolean {
    const { consumableButtonsEnabled, consumableBalance } = this.state.getState();
    return consumableButtonsEnabled[type] && consumableBalance[type] > 0;
  }

  private hideOverlay() {
    this.state.setState((prev) => ({ ...prev, showGoodyOverlay: undefined }));
  }

  /**
   * получаем дефолтные награды для всех типов - 0 обычно
   * и сколько за этот конкретный
   *  **/
  private getRewardsAmount(type: ConsumableType): Record<ConsumableType, number> {
    return {
      ...getDefaultRewardsAmount(),
      [type]: this.props.gameConfig.ads.rewardAmountByType[type],
    };
  }

  private rewardAmountFor(type: ConsumableType): number {
    return this.props.gameConfig.ads.rewardAmountByType[type] ?? 0;
  }

  private tryShowRewardAd(type: ConsumableType): boolean {
    if (!this.gameService.isRewardAdEnabled) return false;
    const rewardsAmount = this.getRewardsAmount(type);
    if (rewardsAmount[type] <= 0) return false;

    this.gameSceneLogicCommands.emit("showRewardAd", { rewardsAmount });
    return true;
  }

  private subscribeToAdEvents() {
    const { gameSceneViewEvents } = this;
    /** просто закрытие рекламы **/
    gameSceneViewEvents.on("onCommonAdClose", () => {
      this.resumeAfterAd();
    });
    /** обработка просмотра рекламы **/
    gameSceneViewEvents.on("onRewardAdClose", (data) => {
      if (data.isReward && data.rewardsAmount) {
        this.addRewards(data.rewardsAmount);
      }
      this.resumeAfterAd();
    });
    /** обработка закрытия анимационного шоу **/
    gameSceneViewEvents.on("onRewardShowAdClose", () => {
      this.resumeAfterAd();
    });
  }

  private addRewards(rewards: Record<ConsumableType, number>) {
    this.state.setState((prev) => {
      const nextBalance = { ...prev.consumableBalance };
      Object.entries(rewards).forEach(([key, inc]) => {
        const type = key as ConsumableType;
        const current = nextBalance[type] ?? 0;
        nextBalance[type] = current + (inc ?? 0);
      });
      return {
        ...prev,
        consumableBalance: nextBalance,
      };
    });
  }

  private resumeAfterAd() {
    // placeholder to extend if needed
  }
}

function getDefaultRewardsAmount(): Record<ConsumableType, number> {
  return {
    UNDO: 0,
    HINT: 0,
    VISION: 0,
    MAGIC: 0,
  };
}
