import { Anima, AnimaMover, GameObject } from "../../../../common";
import { ILootDto, LootTargetRecord } from "../../../../logic";
import { ViewElementBuilder } from "../../../../assets";
import { isLootSidebar } from "../LootSidebar";
import { ILootParticlesAnimationConfig, defaultLootParticlesAnimationConfig } from "./config";

interface IProps {
  scene: Phaser.Scene;

  /** имя хоста (Container) с методом getLootTargets() */
  targetHostName?: string;

  /** сбор лута и его учет, объект должен быть разрушен **/
  onLootItemCollectStart?: (lootDto: ILootDto) => void;
  onLootItemCollected?: (lootDto: ILootDto) => void;
  animationConfig?: Partial<ILootParticlesAnimationConfig>;
}

/***
 *  Использует предоставленные images как частицы
 *
 ***/
export class LootParticles {
  private builder: ViewElementBuilder;
  private readonly targetHostName: string;
  private readonly animationConfig: ILootParticlesAnimationConfig;

  private isActiveEmit = false;
  private remaining = 0;
  private onCompleteCallback?: undefined | (() => void);

  constructor(protected props: IProps) {
    this.builder = new ViewElementBuilder(props.scene);
    this.targetHostName = props.targetHostName ?? "LootSideBar";
    this.animationConfig = {
      ...defaultLootParticlesAnimationConfig,
      ...props.animationConfig,
    };
  }

  emit(args: { loots: ILootDto[]; clickedBounds: Phaser.Geom.Rectangle; onComplete?: () => void }) {
    if (this.isActiveEmit) return;
    this.isActiveEmit = true;
    this.onCompleteCallback = args.onComplete;

    const { scene } = this.props;
    const { loots, clickedBounds } = args;

    const lootItems = loots.map(this.createLootItems.bind(this)).flat();
    if (lootItems.length === 0) {
      this.finishEmit();
      return;
    }
    this.remaining = lootItems.length;
    lootItems.forEach((item) => item.setData("isDone", false));

    /** задаем стартовые позиции - вылет из сундука **/
    const startX = clickedBounds.centerX;
    const startY = clickedBounds.centerY;
    lootItems.forEach((lootItem) => {
      lootItem.setPosition(startX, startY);
    });

    /**
     * если мало - не надо далеко разбрасывать
     * а если много - создаем эффект взрыва
     * **/
    const {
      explodeDistance,
      explodeDistanceDisperse,
      explodeDuration,
      flyDelay,
      flyStepMs,
    } = this.animationConfig;
    const maxDistance = 300;
    const distance = Math.min(maxDistance, lootItems.length * explodeDistance);

    /** 1) Сначала разлёт (explode), 2) потом улетают к целям. **/
    AnimaMover.explode({
      targets: lootItems,
      duration: explodeDuration,
      distance,
      distanceDisperce: explodeDistanceDisperse,
      onComplete: () => {
        scene.time.delayedCall(flyDelay, () => this.collectStaggered(lootItems, flyStepMs));
      },
    });
  }

  destroy() {
    console.log("todo убрать всех картинки");
  }

  /** Создать пачку лут-частиц в текущей реализации **/
  private createLootItems(lootDto: ILootDto) {
    const { builder } = this;

    return Array.from(new Array(lootDto.amount)).map((_) => {
      /** создаем одиночные итемы **/
      const item = builder.lootItem({
        ...lootDto,
        amount: 1,
      });

      /** scale**/
      item.setScale(0.75);

      return item;
    });
  }

  private collectStaggered(lootItems: GameObject[], stepMs: number) {
    const { scene } = this.props;
    const lootTargets = this.getLootTargetsSafe();

    lootItems.forEach((lootItem, index) => {
      scene.time.delayedCall(index * stepMs, () => {
        if (lootItem.scene == null) {
          this.finishOne(lootItem);
          return;
        }
        if (lootTargets) this.collectItemAnimated(lootItem, lootTargets);
        else this.collectItemInstant(lootItem);
      });
    });
  }

  private collectItemAnimated(lootItem: GameObject, lootTargets: LootTargetRecord) {
    const { onLootItemCollectStart } = this.props;
    const lootDto = getLootItemData(lootItem);
    const target = lootTargets[lootDto.type];
    if (!target) {
      this.collectItemInstant(lootItem);
      return;
    }

    onLootItemCollectStart?.(lootDto);

    const targetBounds = target.getBounds();
    const targetX = targetBounds.centerX;
    const targetY = targetBounds.centerY;

    const dist = Phaser.Math.Distance.Between(lootItem.x, lootItem.y, targetX, targetY);
    const { flyDurationMin, flyDurationMax, arcHeightK, arcHeightMin, arcHeightMax } =
      this.animationConfig;
    const duration = Phaser.Math.Clamp(420 + dist * 0.7, flyDurationMin, flyDurationMax);
    const arcHeight = -Phaser.Math.Clamp(70 + dist * arcHeightK, arcHeightMin, arcHeightMax);

    AnimaMover.flyArc({
      target: lootItem,
      targetX,
      targetY,
      duration,
      arcHeight,
      ease: Phaser.Math.Easing.Cubic.InOut,
      onComplete: () => {
        this.logicCollect(lootItem);
      },
    });
  }

  private collectItemInstant(lootItem: GameObject) {
    this.props.onLootItemCollectStart?.(getLootItemData(lootItem));
    Anima.popItem({
      target: lootItem,
      upDistance: -32,
      onComplete: () => {
        this.logicCollect(lootItem);
      },
    });
  }

  private logicCollect(lootItem: GameObject) {
    this.props?.onLootItemCollected?.(getLootItemData(lootItem));
    this.finishOne(lootItem);
    lootItem.destroy();
  }

  private getLootTargetsSafe(): LootTargetRecord | undefined {
    const { scene } = this.props;
    const maybeHost = scene.children.getByName(this.targetHostName);
    if (isLootSidebar(maybeHost)) {
      return maybeHost.getLootTargets();
    }
    return undefined;
  }

  private finishOne(lootItem: GameObject) {
    if (!this.isActiveEmit) return;
    if (lootItem.getData("isDone") === true) return;
    lootItem.setData("isDone", true);

    this.remaining -= 1;
    if (this.remaining > 0) return;

    this.finishEmit();
  }

  private finishEmit() {
    if (!this.isActiveEmit) return;
    this.isActiveEmit = false;
    this.remaining = 0;
    const cb = this.onCompleteCallback;
    this.onCompleteCallback = undefined;
    cb?.();
  }
}

function getLootItemData(lootItem: GameObject){
  return lootItem.getData("lootDto") as ILootDto;
}
