import { GameServicePlayerData } from "./types";
import { getDefaultPlayerData } from "./config";
import { IAdService, MockAdService, YandexAdService } from "../../common/services/AdService";
import {
  allPromisesSettled,
  getErrorMessage,
  getUrlParam,
  InstantDataService,
  LocalDataService,
  LocaleService,
  YandexDataService,
  YandexSdkWrapper
} from "../../common";
import { AdCooldownTracker } from "./utils/adCooldownTracker";
import { mergePlayerData } from "./utils/mergePlayerData";
import { IGameConfig } from "../../logic";
import { setLocaleFromString } from "../../assets";
import { getCheatPlayerData } from "./cheats";

/** состояние **/
interface IGameServiceState {
  playerData: GameServicePlayerData;
}

/**
 * настройки и инжектинг рабочих сервисов
 * **/
export interface IGameServiceOptions {
  gameConfig: IGameConfig;
  /** опциональный логгинг в консоль **/
  isLogging?: boolean;
  /** опциональный key для сохранения данных **/
  playerDataKey?: string;
}

/**
 * @todo доделай
 * Общий фасад для
 * - сохранения данных и чтения
 * - включения рекламы
 * **/
export class GameService {
  private state: IGameServiceState;
  private readonly localDataService: InstantDataService;
  /** облачный сервис сохранения доступен только для авторизованных пользователей **/
  private cloudDataService: InstantDataService | undefined;
  private readonly playerDataKey: string;
  private readonly adCooldown: AdCooldownTracker;
  private adService?: IAdService;
  private readonly yandexSdkWrapper: YandexSdkWrapper;
  private saveTimer?: number;
  protected lastSaveTimeMs?: number;
  private readonly gameConfig: IGameConfig;

  constructor(private readonly props: IGameServiceOptions) {
    this.gameConfig = props.gameConfig;

    const appId = this.gameConfig.gameId;
    this.playerDataKey = props.playerDataKey ?? `${appId}-playerData`;
    this.state = {
      playerData: mergePlayerData(getDefaultPlayerData(this.gameConfig), undefined),
    };
    this.adCooldown = new AdCooldownTracker({
      ...this.gameConfig.ads.cooldowns,
    });
    this.yandexSdkWrapper = new YandexSdkWrapper({ isLogging: props.isLogging });
    this.localDataService = new LocalDataService({
      appId,
    });
  }

  /****
   * Public
   ****/

  /** инициализация и загрузка - ставь в Boot scene preload **/
  async preload(): Promise<void> {
    /**
     * Добавляй сюда загрузки сервисов
     * ошибка загрузки не прервет остальные
     * благодаря allPromisesSettled (полифиллу Promise.allSettled)
     * **/
    const tasks = [
      { name: "localDataService", promise: this.localDataService.preload() },
      { name: "yandexSdk", promise: this.yandexSdkWrapper.init() },
    ].filter((task): task is { name: string; promise: Promise<void> } => !!task.promise);

    const results = await allPromisesSettled(tasks.map((t) => t.promise));

    results.forEach((r, index) => {
      if (r.status === "rejected") {
        this.warn(`${tasks[index].name} preload failed`, r.reason);
      }
    });

    await this.initCloudDataService();
    this.initAds();
    this.initLocale();
    await this.readPlayerData();
  }

  get isShopEnabled(): boolean {
    return false;
  }

  getGameConfig(): IGameConfig {
    return this.gameConfig;
  }

  get isFullAdEnabled(): boolean {
    return this.adService != null && this.adCooldown.canShowCommon();
  }

  get isRewardAdEnabled(): boolean {
    return this.adService != null && this.adCooldown.canShowReward();
  }

  /**
   * мгновенный доступ к данным игрока
   * внимание - используйте отдельные поля оттуда
   * не модифицируйте объект по ссылке
   *  **/
  getPlayerData(): GameServicePlayerData {
    const { settings, consumables } = this.state.playerData;

    /** Это сделано чтобы избежать модификации по ссылке **/
    return {
      settings: {
        ...settings,
      },
      consumables: {
        ...consumables,
      },
    };
  }

  /** синхронно обновляет данные игрока,
   * возможно вызовет сохранение
   * debounce частых сохранений - на стороне сервисов
   * **/
  setPlayerData(partial: Partial<GameServicePlayerData>): void {
    this.state.playerData = mergePlayerData(this.state.playerData, partial);
    this.log("playerData updated = ", this.state.playerData);
    this.scheduleSave();
  }

  showCommonAd(onClose?: (args: { wasShown: boolean; error?: string }) => void): void {
    try {
      if (!this.adService) {
        onClose?.({ wasShown: false, error: "adService not available" });
        return;
      }
      if (!this.isFullAdEnabled) {
        onClose?.({ wasShown: false, error: "ad is not allowed yet" });
        return;
      }
      const mark = () => this.adCooldown.markCommon();
      this.adService.showCommonAd({
        onOpen: mark,
        onClose: (args) => {
          if (args.wasShown) {
            mark();
          }
          onClose?.(args);
        },
      });
    } catch (e) {
      onClose?.({ wasShown: false, error: getErrorMessage(e) });
    }
  }

  showRewardedAd(
    onClose?: (args: { wasShown: boolean; error?: string; isReward: boolean }) => void,
  ): void {
    try {
      if (!this.adService || !this.isRewardAdEnabled) {
        onClose?.({ wasShown: false, isReward: false, error: "ad not available" });
        return;
      }
      const mark = () => this.adCooldown.markReward();
      this.adService.showRewardedAd({
        onOpen: mark,
        onClose: (args) => {
          if (args.wasShown) {
            mark();
          }
          onClose?.(args);
        },
      });
    } catch (e) {
      onClose?.({ wasShown: false, error: getErrorMessage(e), isReward: false });
    }
  }

  /****
   * Private
   ****/

  /** взять Player Data из дата сервисов,
   *  их get мгновеннен (читает из кэша)**/
  private async readPlayerData(): Promise<void> {
    try {
      const read = (service: InstantDataService | undefined) =>
        service?.getData<GameServicePlayerData>(this.playerDataKey);

      /** облачный сервис получает приоритет загрузки
       *  не надо писать что потеряются локальные данные - так и задумано
       *  если есть облачный сервис - сохранение идет через него
       *  мы не можем перезаписывать облачные данные локальными
       *  - это будет брешь и чит для юзеров
       * **/
      const primaryService = this.cloudDataService ?? this.localDataService;

      /** данные могут быть подставлены через чит **/
      const savedPlayerData = getCheatPlayerData() ?? read(primaryService);

      /** в любом случае идет частичное замещение полей **/
      this.state.playerData = mergePlayerData(
        getDefaultPlayerData(this.gameConfig),
        savedPlayerData,
      );
    } catch (e) {
      this.warn(e);
    }
  }

  private async initCloudDataService(): Promise<void> {
    const player = this.yandexSdkWrapper.getPlayer();
    if (!player) return;
    this.cloudDataService = new YandexDataService(player);
    try {
      await this.cloudDataService.preload();
    } catch (error) {
      this.warn("cloudDataService preload failed", error);
    }
  }

  private initAds(): void {
    if (this.adService != null) return;
    if (this.isMockAdEnabled) {
      this.adService = new MockAdService();
    } else {
      const sdk = this.yandexSdkWrapper.getSDK();
      this.adService = sdk ? new YandexAdService(sdk) : undefined;
    }
    this.adCooldown.start();
  }

  private get isMockAdEnabled(): boolean {
    return getUrlParam("mockAd") != null;
  }

  private initLocale() {
    /** это очень простой сервис, мог бы быть функцией **/
    new LocaleService({
      sdk: this.yandexSdkWrapper.getSDK(),
      setLocaleFromString: setLocaleFromString,
    });
  }

  /****
   * Private logging
   ****/
  private log(...args: unknown[]) {
    if (!this.props.isLogging) return;
    console.log(...args);
  }

  // работает всегда
  private warn(...args: unknown[]) {
    console.warn(...args);
  }

  private scheduleSave() {
    const debounceMs = this.gameConfig.dataServiceOptions.saveDebounceMs;
    const now = Date.now();
    const lastSaveTimeMs = this.lastSaveTimeMs;

    if (lastSaveTimeMs == null || now - lastSaveTimeMs >= debounceMs) {
      if (this.saveTimer != null) {
        clearTimeout(this.saveTimer);
        this.saveTimer = undefined;
      }
      this.savePlayerData();
      return;
    }

    const safeDelayMs = Math.max(0, lastSaveTimeMs + debounceMs - now);
    if (this.saveTimer != null) {
      clearTimeout(this.saveTimer);
    }
    this.saveTimer = window.setTimeout(() => {
      this.saveTimer = undefined;
      this.savePlayerData();
    }, safeDelayMs);
  }

  private savePlayerData() {
    /** локальное сохранение - внутри try-catch  **/
    this.localDataService.setData(this.playerDataKey, this.state.playerData);
    /** облачное сохранение - внутри try-catch **/
    this.cloudDataService?.setData(this.playerDataKey, this.state.playerData);
    this.lastSaveTimeMs = Date.now();
  }
}
