import { makeRandomAmount, throwDice } from "../../../common";
import {ConsumableType} from '../../../logic';

interface IProps {
  /** множители лута для разных сундуков **/
  lootMultipliers: number[];
  /** вероятность выпдаения от 0 до 1 **/
  lootProbability: Record<ConsumableType, number>;
  /** разброс величины лута в абсолютных единицах, идет в положительную сторону **/
  lootDispersion?: number;
}

export const makeLoots = ({ lootMultipliers, lootProbability, lootDispersion = 1 }: IProps): Record<ConsumableType, number>[] => {
  return lootMultipliers.map((lootK) => {

    return {
      UNDO: makeRandomAmount({
        lootK,
        disperse: lootDispersion,
        probability: lootProbability.UNDO
      }),
      HINT: makeRandomAmount({
        lootK,
        disperse: lootDispersion,
        probability: lootProbability.HINT
      }),
      VISION: makeRandomAmount({
        lootK,
        disperse: lootDispersion,
        probability: lootProbability.VISION
      }),
      MAGIC: makeRandomAmount({
        lootK,
        disperse: lootDispersion,
        probability: lootProbability.MAGIC
      }),
    };
  });
};
