import { Align } from "@kvisaz/phaser-sugar";
import { ConsumableOverlays, InfoUi, ShopOverlay, UiButtonsSideBar } from "./components";
import { KlondikeWrap } from "./components/KlondikeWrap";
import { GameSceneViewLogic } from "./logic";
import { SettingsUi } from "../shared";
import { GameFinishOverlay } from "./components/GameFinishOverlay";
import { CommonAdsOverlay } from "./components/CommonAdsOverlay";
import { RewardAdsOverlay } from "./components/RewardAdsOverlay";
import { GameServiceProvider } from "../../services";

interface IProps {
  scene: Phaser.Scene;
}

export class GameSceneView {
  private unSubs: (() => void)[] = [];
  private gameLogic: GameSceneViewLogic;

  constructor(private props: IProps) {
    const { scene } = props;
    const align = new Align();

    const padding = 16;

    /** логика игровой сцены **/
    this.gameLogic = new GameSceneViewLogic({
      gameConfig: GameServiceProvider.get().getGameConfig(),
    });
    this.unSubs.push(() => this.gameLogic.destroy());

    const infoUi = new InfoUi({
      scene,
      gameState: this.gameLogic.observable(),
    });
    align.anchorSceneScreen(scene).topIn(infoUi, padding).leftIn(infoUi, padding);
    this.unSubs.push(() => infoUi.destroy());

    /** кнопки для игры **/
    const sideBar = new UiButtonsSideBar({
      scene,
      gameSceneViewEvents: this.gameLogic.gameSceneViewEvents,
      gameState: this.gameLogic.observable(),
    });
    align
      .anchor(infoUi)
      .bottomTo(sideBar, padding * 3)
      .leftIn(sideBar, padding);
    this.unSubs.push(() => sideBar.destroy());

    /** игра **/
    const klondikeWrap = new KlondikeWrap({
      scene,
      gameSceneViewEvents: this.gameLogic.gameSceneViewEvents,
      gameSceneLogicCommands: this.gameLogic.gameSceneLogicCommands,
    });
    this.unSubs.push(() => klondikeWrap.destroy());

    /** оверлеи для трюков игры  **/
    const overlays = new ConsumableOverlays({
      scene,
      gameState: this.gameLogic.observable(),
    });
    this.unSubs.push(() => overlays.destroy());

    /** кнопка настроек с диалогом **/
    const settingsUi = new SettingsUi({
      scene,
    });
    align
      .anchorSceneScreen(scene)
      .topIn(settingsUi, padding)
      .rightIn(settingsUi, -padding * 2);
    this.unSubs.push(() => settingsUi.destroy());

    /** кнопка магазина с диалогом маназина **/
    const shopOverlay = new ShopOverlay({
      scene,
    });
    align
      .anchor(settingsUi)
      .bottomTo(shopOverlay, padding * 1.5)
      .rightIn(shopOverlay);
    this.unSubs.push(() => shopOverlay.destroy());

    /** gameFinish screen **/
    const gameFinishOverlay = new GameFinishOverlay({
      scene,
    });
    this.gameLogic.gameSceneLogicCommands.on("showGameFinish", data => {
      gameFinishOverlay.showScreen(data, ()=>this.gameLogic.gameSceneViewEvents.emit('onGameFinishClose'));
    });

    const adsOverlay = new CommonAdsOverlay({
      scene,
      commands: this.gameLogic.gameSceneLogicCommands,
      viewEvents: this.gameLogic.gameSceneViewEvents,
    });
    this.unSubs.push(() => adsOverlay.destroy());

    const rewardAdsOverlay = new RewardAdsOverlay({
      scene,
      commands: this.gameLogic.gameSceneLogicCommands,
      viewEvents: this.gameLogic.gameSceneViewEvents,
    });
    this.unSubs.push(() => rewardAdsOverlay.destroy());

    /** старт новой игры через логику **/
    this.gameLogic.startNewGame({ shuffleDeck: true });
  }

  destroy() {
    this.unSubs.forEach((unSub) => unSub());
  }
}
