interface IProps {
  commonMs: number;
  rewardMs: number;
}

export class AdCooldownTracker {
  private startTime: number;
  private lastCommonTime: number;
  private lastRewardTime: number;

  constructor(private readonly props: IProps) {
    this.startTime = Date.now();
    this.lastCommonTime = this.startTime;
    this.lastRewardTime = this.startTime;
  }

  start(now = Date.now()): void {
    this.startTime = now;
    this.lastCommonTime = now;
  }

  canShowCommon(now = Date.now()): boolean {
    return now - this.lastCommonTime >= this.props.commonMs;
  }

  canShowReward(now = Date.now()): boolean {
    const last = this.lastRewardTime;
    return now - last >= this.props.rewardMs;
  }

  markCommon(now = Date.now()): void {
    this.lastCommonTime = now;
  }

  markReward(now = Date.now()): void {
    this.lastRewardTime = now;
  }
}
