import { Align } from "@kvisaz/phaser-sugar";
import { ViewElementBuilder } from "../../../assets";
import { Observable } from "../../../common";
import { GameLogicState } from "../logic";

interface IProps {
  scene: Phaser.Scene;
  gameState: Observable<GameLogicState>;
}

/**
 *  - очки за игру (исходят от klondike и ставятся в стейт логики)
 *  - таймер не используется, так как в нем пока нет смысла
 **/
export class InfoUi extends Phaser.GameObjects.Container {
  constructor(private readonly props: IProps) {
    super(props.scene);
    const { scene, gameState } = props;
    const builder = new ViewElementBuilder(scene);
    const align = new Align();

    const initialState = gameState.getState();
    const scoreInfo = builder.gameInfoScoreTable(initialState.score);
    // const timeInfo = builder.gameInfoTimeTable(initialState.timeMs);

    // align.anchor(scoreInfo).leftIn(timeInfo).bottomTo(timeInfo, 16);
    this.add([scoreInfo]);
    scene.add.existing(this);

    // gameState.on((state) => {
    //   timeInfo.setTime(state.timeMs);
    // }, "timeMs");

    gameState.on((state) => {
      scoreInfo.setScore(state.score);
    }, "score");
  }
}
